import{_ as r}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/OFF.BrU7kQE-.js";import{_ as a}from"./chunks/ON.DXVlsWbj.js";import{_ as i}from"./chunks/M-S-SW8c.OZF8VB_x.js";import{_ as s,o as n,c as o,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Montres connectées","description":"","frontmatter":{"source_hash":"3b41debaf8","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/smartwatch/smartwatch.md","filePath":"fr/smartwatch/smartwatch.md"}'),c={name:"fr/smartwatch/smartwatch.md"};function d(p,e,m,u,h,b){return n(),o("div",null,[...e[0]||(e[0]=[l('<div class="admonition xdrip"><p class="admonition-title"><img src="'+r+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Options montre intelligente</p></div><h2 id="xdrip-direct-integration" tabindex="-1">Intégration directe dans xDrip <a class="header-anchor" href="#xdrip-direct-integration" aria-label="Permalink to &quot;Intégration directe dans xDrip {#xdrip-direct-integration}&quot;">​</a></h2><p>xDrip prend en charge une large gamme de montres connectées.</p><h3 id="android-wear-integration" tabindex="-1"><a href="./wear.html">Intégration Wear OS</a> <a class="header-anchor" href="#android-wear-integration" aria-label="Permalink to &quot;[Intégration Wear OS](./wear) {#android-wear-integration}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Intégration Wear OS</p></div><p>C&#39;est avec les montres Wear OS que l&#39;intégration est la plus complète, car elles exécutent localement une partie de l&#39;application xDrip.</p><p>L&#39;extension Wear de xDrip n&#39;est plus développée.</p><p>Si vous avez besoin de plus de cadrans ou de personnalisations, vous pouvez utiliser <a href="https://github.com/FreDiabetics/xDrip--Tasker-Tizen-Watchface-Integration/blob/master/README.md" target="_blank" rel="noreferrer">Tasker</a> (mais pas comme collecteur autonome).</p><h3 id="pebble-integration" tabindex="-1"><a href="./pebble.html">Intégration Pebble</a> <a class="header-anchor" href="#pebble-integration" aria-label="Permalink to &quot;[Intégration Pebble](./pebble) {#pebble-integration}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Intégration Pebble</p></div><p>L&#39;utilisation de la montre Pebble est une étape historique du CGM dans le Cloud. Les montres Pebble d&#39;origine ont été abandonnées en 2016, lorsque Pebble a été rachetée par Fitbit (leurs ressources ont été déplacées vers des archives et vers <a href="https://rebble.io/" target="_blank" rel="noreferrer">rebble.io</a>). De nouveaux modèles Pebble ont été relancés en 2025 : xDrip prend en charge les deux, voir <a href="./pebble.html">Intégration Pebble</a>.</p><h3 id="amazfit-sync-service" tabindex="-1"><a href="https://crazyinfo.de/2018/07/25/xdrip-smartwatch-widget-fuer-amazfit-pace-stratos/" target="_blank" rel="noreferrer">Service de synchronisation AmazFit</a> <a class="header-anchor" href="#amazfit-sync-service" aria-label="Permalink to &quot;[Service de synchronisation AmazFit](https://crazyinfo.de/2018/07/25/xdrip-smartwatch-widget-fuer-amazfit-pace-stratos/) {#amazfit-sync-service}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Service de synchronisation AmazFit</p></div><p>AmazFit n&#39;était utilisé que pour les modèles Pace et Stratos.<br><strong>Vous ne pouvez pas utiliser cette fonction avec d&#39;autres montres AmazFit.</strong></p><h3 id="bluejay-watch" tabindex="-1"><a href="./bluejay.html">BlueJay Watch</a> <a class="header-anchor" href="#bluejay-watch" aria-label="Permalink to &quot;[BlueJay Watch](./bluejay) {#bluejay-watch}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch</p></div><p>BlueJay est un formidable compagnon pour votre capteur Dexcom, avec ou sans xDrip, avec ou sans téléphone.</p><h3 id="lefun-band" tabindex="-1"><a href="https://www.lefunsmart.com/collections/smartwatches" target="_blank" rel="noreferrer">Bracelet Lefun</a> <a class="header-anchor" href="#lefun-band" aria-label="Permalink to &quot;[Bracelet Lefun](https://www.lefunsmart.com/collections/smartwatches) {#lefun-band}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Bracelet Lefun</p></div><p>L&#39;intégration du bracelet LeFun a été l&#39;une des premières pour les bracelets connectés ; elle s&#39;utilise de préférence en mmol/l.<br> À moins que vous ne possédiez encore un bracelet LeFun W3, F3, F3S, F11 ou F12, elle n&#39;a plus aucune utilité aujourd&#39;hui.</p><h3 id="miband" tabindex="-1"><a href="./miband.html">MiBand</a> <a class="header-anchor" href="#miband" aria-label="Permalink to &quot;[MiBand](./miband) {#miband}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">MiBand</p></div><p>L&#39;intégration MiBand est le fruit de l&#39;énorme travail d&#39;<a href="https://bigdigital.home.blog/" target="_blank" rel="noreferrer">Artem</a>.<br> De nombreuses montres et bracelets connectés sont désormais pris en charge grâce à l&#39;application compagnon WatchDrip+.</p><div class="info custom-block"><p class="custom-block-title">Désactivez MiBand dans xDrip si vous utilisez WatchDrip+</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser le bracelet MiBand <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div></div><h2 id="smartwatch-sensors" tabindex="-1">Capteurs des montres connectées <a class="header-anchor" href="#smartwatch-sensors" aria-label="Permalink to &quot;Capteurs des montres connectées {#smartwatch-sensors}&quot;">​</a></h2><p>xDrip peut utiliser les capteurs des montres connectées compatibles.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser les données de santé <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>xDrip peut demander l&#39;activation du capteur de fréquence cardiaque, et vous pouvez lisser ce graphique.</p><div class="admonition xdripitem"><p class="admonition-title">Capteur de fréquence cardiaque <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>Lorsque c&#39;est possible, vous pouvez laisser xDrip collecter des données de santé comme la fréquence cardiaque et les pas.</p><p>Deux icônes supplémentaires apparaîtront sur l&#39;écran principal et, si elles sont activées, des représentations graphiques :</p><ol><li>Un graphique bleu foncé pour la fréquence cardiaque</li><li>Une ligne en nuage cyan clair pour les pas</li></ol><img src="'+i+'" style="zoom:75%;"><h2 id="other-smartwatches" tabindex="-1">Autres montres connectées <a class="header-anchor" href="#other-smartwatches" aria-label="Permalink to &quot;Autres montres connectées {#other-smartwatches}&quot;">​</a></h2><p>D&#39;autres montres et appareils peuvent recevoir les données de xDrip même s&#39;ils ne sont pas directement intégrés à l&#39;application.</p><div class="info custom-block"><p class="custom-block-title">Info</p><p>Pour que xDrip envoie les données, vous devez activer le <a href="./../use/interapp.html#web-service">service web</a> de xDrip.</p></div><h3 id="android-wear" tabindex="-1">Android Wear <a class="header-anchor" href="#android-wear" aria-label="Permalink to &quot;Android Wear {#android-wear}&quot;">​</a></h3><p><a href="https://github.com/pachi81/GlucoDataHandler" target="_blank" rel="noreferrer">GlucoDataHandler</a> accepte xDrip comme source de données. L&#39;application est disponible sur le <a href="https://play.google.com/store/apps/details?id=de.michelinside.glucodatahandler" target="_blank" rel="noreferrer">Google Play Store</a>.</p><h3 id="android-auto" tabindex="-1">Android Auto <a class="header-anchor" href="#android-auto" aria-label="Permalink to &quot;Android Auto {#android-auto}&quot;">​</a></h3><p><a href="https://github.com/pachi81/GlucoDataAuto" target="_blank" rel="noreferrer">GlucoDataAuto</a> est l&#39;extension Android Auto de GlucoDataHandler.</p><h3 id="fitbit" tabindex="-1">Fitbit <a class="header-anchor" href="#fitbit" aria-label="Permalink to &quot;Fitbit {#fitbit}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Google arrête Sense/Ionic/Versa</p><p>Tenez compte du fait que ces produits arriveront en fin de vie dans un avenir proche.</p></div><div class="warning custom-block"><p class="custom-block-title">Indisponible pour les utilisateurs de l&#39;UE</p><p>Google a <a href="https://support.google.com/fitbit/answer/14237121?hl=en" target="_blank" rel="noreferrer">supprimé</a> cette possibilité depuis juin 2024. Les cadrans déjà installés ne sont pas concernés, mais les nouveaux utilisateurs ne peuvent plus installer de cadrans personnalisés. Vous devez utiliser un VPN pour contourner le problème.</p></div><div class="warning custom-block"><p class="custom-block-title">Android 9 et versions antérieures</p><p>Les utilisateurs d&#39;Android dans une version inférieure à 10 doivent rétrograder l&#39;application Fitbit vers une version précédente, comme la 3.58, et désactiver les mises à jour automatiques. Vous la trouverez sur <a href="https://fitbit.en.aptoide.com/versions" target="_blank" rel="noreferrer">Aptoide</a> et d&#39;autres serveurs d&#39;hébergement d&#39;apk.</p></div><h5 id="glance" tabindex="-1"><a href="https://gallery.fitbit.com/details/7b5d9822-7e8e-41f9-a2a7-e823548c001c" target="_blank" rel="noreferrer">Glance</a> <a class="header-anchor" href="#glance" aria-label="Permalink to &quot;[Glance](https://gallery.fitbit.com/details/7b5d9822-7e8e-41f9-a2a7-e823548c001c) {#glance}&quot;">​</a></h5><p>Ionic/Sense/Versa/Versa 2/Versa 3/Versa 4/Versa Lite</p><p><a href="https://glancewatchface.com/" target="_blank" rel="noreferrer">Site web</a></p><h5 id="sentinel" tabindex="-1"><a href="https://gallery.fitbit.com/developer/b50ac7f5-b932-441a-be18-e258b17c736b" target="_blank" rel="noreferrer">Sentinel</a> <a class="header-anchor" href="#sentinel" aria-label="Permalink to &quot;[Sentinel](https://gallery.fitbit.com/developer/b50ac7f5-b932-441a-be18-e258b17c736b) {#sentinel}&quot;">​</a></h5><p>Sentinel Elite pour Sense/Versa 3<br> Sentinel Pro pour Ionic/Versa/Versa 2/Versa Lite</p><p>Groupe Facebook : <a href="https://www.facebook.com/groups/3185325128159614" target="_blank" rel="noreferrer">Sentinel</a></p><h5 id="marclock" tabindex="-1"><a href="https://gallery.fitbit.com/details/9eacf714-5b23-40c8-9621-ded74bd9edf9" target="_blank" rel="noreferrer">Marclock</a> <a class="header-anchor" href="#marclock" aria-label="Permalink to &quot;[Marclock](https://gallery.fitbit.com/details/9eacf714-5b23-40c8-9621-ded74bd9edf9) {#marclock}&quot;">​</a></h5><p>Ionic/Sense/Versa/Versa 2/Versa Lite</p><p><a href="https://github.com/cramis1/Marclock-with-CGM-weather/blob/master/README.md" target="_blank" rel="noreferrer">Instructions</a></p><h5 id="analog-cgm" tabindex="-1"><a href="https://gallery.fitbit.com/details/4d7b46b1-aaba-49b4-aa10-183321014dd3" target="_blank" rel="noreferrer">Analog CGM</a> <a class="header-anchor" href="#analog-cgm" aria-label="Permalink to &quot;[Analog CGM](https://gallery.fitbit.com/details/4d7b46b1-aaba-49b4-aa10-183321014dd3) {#analog-cgm}&quot;">​</a></h5><h5 id="orbits-ns" tabindex="-1"><a href="https://gallery.fitbit.com/details/44de5c81-b77c-4f90-baa8-38f3e3d28695" target="_blank" rel="noreferrer">Orbits NS</a> <a class="header-anchor" href="#orbits-ns" aria-label="Permalink to &quot;[Orbits NS](https://gallery.fitbit.com/details/44de5c81-b77c-4f90-baa8-38f3e3d28695) {#orbits-ns}&quot;">​</a></h5><h5 id="radial-cgm" tabindex="-1"><a href="https://gallery.fitbit.com/details/0173730e-5381-4495-bc6e-6ec93c8df029" target="_blank" rel="noreferrer">Radial CGM</a> <a class="header-anchor" href="#radial-cgm" aria-label="Permalink to &quot;[Radial CGM](https://gallery.fitbit.com/details/0173730e-5381-4495-bc6e-6ec93c8df029) {#radial-cgm}&quot;">​</a></h5><p>Ionic/Versa/Versa 2/Versa Lite/Versa 3/Sense</p><h3 id="samsung-gear" tabindex="-1">Samsung Gear <a class="header-anchor" href="#samsung-gear" aria-label="Permalink to &quot;Samsung Gear {#samsung-gear}&quot;">​</a></h3><p><a href="https://play.google.com/store/apps/details?id=sk.trupici.g_watch" target="_blank" rel="noreferrer">G-Watch</a> est le moyen le plus simple d&#39;y parvenir. Consultez le <a href="https://github.com/trupici/G-Watch-Wear/wiki" target="_blank" rel="noreferrer">wiki</a>.</p><p>Vous pouvez aussi utiliser <a href="https://github.com/FreDiabetics/xDrip--Tasker-Tizen-Watchface-Integration/blob/master/README.md" target="_blank" rel="noreferrer">Tasker</a> pour afficher les données de xDrip sur votre montre Samsung Gear.</p><h3 id="garmin" tabindex="-1">Garmin <a class="header-anchor" href="#garmin" aria-label="Permalink to &quot;Garmin {#garmin}&quot;">​</a></h3><p>De nombreux cadrans Garmin sont disponibles ; vérifiez que votre modèle est pris en charge.</p><p>Par <a href="https://apps.garmin.com/en-US/developer/e985e9ec-bcf6-4aef-bfe9-77c1c93fc854/apps" target="_blank" rel="noreferrer">Horsetooth</a></p><p>Par <a href="https://apps.garmin.com/en-US/developer/f9420c47-810f-47ac-a7dd-9fa7b8ecd22d/apps" target="_blank" rel="noreferrer">andreas-may</a></p><p>Par <a href="https://apps.garmin.com/en-US/developer/b2d30711-2708-4f3a-8e83-009c16d07081/apps" target="_blank" rel="noreferrer">John_</a></p><p>Par <a href="https://apps.garmin.com/en-US/developer/b61690c3-5e5c-4c4e-afe9-434db16542a9/apps" target="_blank" rel="noreferrer">Roboleo1010</a></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',68)])])}const q=s(c,[["render",d]]);export{_ as __pageData,q as default};
